<?php
// SPDX-License-Identifier: AGPL-3.0-only
use Panel\Services\{Transfer,DomainService,ZoneRecords};
use Panel\Core\AppException;

$db->run("DELETE FROM settings WHERE name='preview_mode'");
$db->run("UPDATE jobs SET status='cancelled' WHERE status NOT IN ('completed','cancelled')");
$db->run('UPDATE domains SET next_check_at=NULL');$saas->ready=true;
$targetWorker=new \Panel\Jobs\Worker($db,$cloud,$fakeDiagnostics);
$ipTargets=['1.1.1.1','8.8.8.8','2606:4700:4700::1111'];
$poolEntry=$configs->save('entries',['name'=>'Measured IP group','kind'=>'ip','targets'=>$ipTargets],'test');
$targetEntry=$configs->save('entries',['name'=>'Third-party preferred target','kind'=>'cname','targets'=>['edge.target.test']],'test');
$targetBase=['profile_id'=>$profile,'check'=>['path'=>'/','statuses'=>[200],'keyword'=>'']];
$poolResult=$zoneRecords->create($customerZone,$targetBase+['name'=>'pool-target','type'=>'A','source_ip'=>'9.9.9.31','entry_id'=>$poolEntry],'test');$poolId=$poolResult['items'][0]['domain_id'];
tick($targetWorker,$db,8);
$poolDetail=$service->detail($poolId);$poolRecords=array_values(array_filter($dns->records,fn($r)=>$r['name']==='pool-target.customer.test'));
check($poolDetail['status']==='active'&&count($poolRecords)===3,'selecting an IP group provisions all three visitor DNS records');
check(count(array_filter($poolRecords,fn($r)=>$r['type']==='A'))===2&&count(array_filter($poolRecords,fn($r)=>$r['type']==='AAAA'))===1,'mixed preferred IP groups preserve IPv4 and IPv6 record types');
check(array_column($poolRecords,'content')===$ipTargets&&!array_filter($poolRecords,fn($r)=>$r['proxied']),'preferred group addresses stay separate from the source IP and disable visitor proxying');
check($poolDetail['applied_config']['origin']['source_ip']==='9.9.9.31','multi-IP preferred target does not replace the website source IP');
$cnameInput=$targetBase+['name'=>'cname-source','type'=>'CNAME','source_hostname'=>'Origin.backend.test.','entry_id'=>$targetEntry];
$cnameResult=$zoneRecords->create($customerZone,$cnameInput,'test');$cnameId=$cnameResult['items'][0]['domain_id'];tick($targetWorker,$db,8);
$cnameDetail=$service->detail($cnameId);$cnameOrigin=$cnameDetail['applied_config']['origin'];
check($cnameDetail['status']==='active'&&$cnameOrigin['source_hostname']==='origin.backend.test','manual CNAME origin is normalized and completes onboarding');
$aliasRecords=array_values(array_filter($saas->records,fn($r)=>$r['name']===$cnameOrigin['hostname']));
check(count($aliasRecords)===1&&$aliasRecords[0]['type']==='CNAME'&&$aliasRecords[0]['content']==='origin.backend.test'&&$aliasRecords[0]['proxied'],'CNAME source gets its own owned proxied alias in the SaaS zone');
check($saas->hostnames[$cnameDetail['cf_hostname_id']]['custom_origin_server']===$cnameOrigin['hostname'],'SaaS hostname uses the managed source alias rather than the preferred target');
$cnameVisitor=array_values(array_filter($dns->records,fn($r)=>$r['name']==='cname-source.customer.test'));
check(count($cnameVisitor)===1&&$cnameVisitor[0]['content']==='edge.target.test','visitor CNAME points to the selected preferred domain independently of the CNAME source');
$unchanged=$service->configure($cnameId,['type'=>'CNAME','source_hostname'=>'origin.backend.test','expected_version'=>1],'test');
check(!$unchanged['changed'],'saving an unchanged CNAME source does not enqueue another change');
rejects(fn()=>$zoneRecords->create($customerZone,[...$cnameInput,'name'=>'bad-source','source_ip'=>'9.9.9.31'],'test'),422,'origin IP and CNAME cannot be submitted together');
rejects(fn()=>$zoneRecords->create($customerZone,[...$cnameInput,'name'=>'self-source','source_hostname'=>'self-source.customer.test'],'test'),422,'CNAME origin cannot loop back to its own business hostname');
rejects(fn()=>$zoneRecords->create($customerZone,[...$cnameInput,'name'=>'ip-cname','source_hostname'=>'8.8.8.8'],'test'),422,'CNAME origin rejects an IP value');
check(!array_filter($configs->list()['origins'],fn($origin)=>(int)$origin['id']===(int)$cnameOrigin['id']),'automatic CNAME source aliases stay out of shared preset lists');
rejects(fn()=>$configs->update('origins',(int)$cnameOrigin['id'],['name'=>'must not edit alias'],'test'),409,'automatic CNAME sources must be edited through the domain record');
$service->configure($cnameId,['type'=>'CNAME','source_hostname'=>'second.backend.test','expected_version'=>1],'test');tick($targetWorker,$db,6);
check($service->detail($cnameId)['applied_config']['origin']['source_hostname']==='second.backend.test','editing a CNAME source applies an independent new source alias');
$service->action($cnameId,'rollback','test');tick($targetWorker,$db,6);
check($service->detail($cnameId)['applied_config']['origin']['source_hostname']==='origin.backend.test','CNAME source rollback restores the previous source snapshot');
$callsBefore=count($saas->requests);
$direct=$zoneRecords->create($customerZone,$targetBase+['name'=>'direct-cname','type'=>'CNAME','source_hostname'=>'plain.backend.test','entry_id'=>$targetEntry,'dns_mode'=>'dns_only'],'test');$directId=$direct['items'][0]['domain_id'];tick($targetWorker,$db,4);
$directRecords=array_values(array_filter($dns->records,fn($r)=>$r['name']==='direct-cname.customer.test'));
check(count($saas->requests)===$callsBefore&&count($directRecords)===1&&$directRecords[0]['content']==='plain.backend.test'&&!$directRecords[0]['proxied'],'gray-cloud CNAME source writes direct DNS without using SaaS');
$service->configure($directId,['dns_mode'=>'proxied','expected_version'=>1],'test');tick($targetWorker,$db,4);
$directRecords=array_values(array_filter($dns->records,fn($r)=>$r['name']==='direct-cname.customer.test'));
check(count($directRecords)===1&&$directRecords[0]['type']==='CNAME'&&$directRecords[0]['proxied']&&$directRecords[0]['ttl']===1,'orange-cloud CNAME source preserves its target and uses automatic TTL');
$exporter=new Transfer($db,$configs);$doc=$exporter->export($customerZone);
check($doc['format_version']===3,'CNAME origin plans use export format version three');
$portable=array_values(array_filter($doc['records'],fn($record)=>$record['hostname']==='cname-source.customer.test'))[0];
check($portable['source_hostname']==='origin.backend.test'&&!isset($portable['origin_ref']),'CNAME exports preserve the actual origin rather than a runtime source alias');
$doc['records']=[$portable];$doc['entries']=array_values(array_filter($doc['entries'],fn($e)=>$e['ref']===$portable['entry_ref']));$doc['origins']=[];
$doc['profiles']=array_values(array_filter($doc['profiles'],fn($p)=>$p['ref']===$portable['profile_ref']));
$accountRefs=[$portable['dns_account_ref'],$doc['profiles'][0]['account_ref']];$doc['accounts']=array_values(array_filter($doc['accounts'],fn($a)=>in_array($a['ref'],$accountRefs,true)));
$bindings=[];foreach($doc['accounts'] as $account){$bindings[$account['ref']]=(int)$account['ref'];}
$importPreview=$exporter->import(['document'=>$doc,'account_bindings'=>$bindings,'preview'=>true],'test');
check($importPreview['reused']===1&&$importPreview['new_tasks']===0,'CNAME source export can preview-import and reuse its existing domain');
$doc['format_version']=2;rejects(fn()=>$exporter->import(['document'=>$doc,'account_bindings'=>$bindings,'preview'=>true],'test'),422,'older export formats reject CNAME origin fields');$doc['format_version']=3;
$doc['records'][0]['hostname']='clone-cname.customer.test';$beforeDomains=(int)$db->value('SELECT COUNT(*) FROM domains');
$newPreview=$exporter->import(['document'=>$doc,'account_bindings'=>$bindings,'preview'=>true],'test');
check($newPreview['new_tasks']===1&&(int)$db->value('SELECT COUNT(*) FROM domains')===$beforeDomains,'new CNAME origin import preview leaves no aliases or tasks behind');
$service->remove($cnameId,['mode'=>'delete_remote'],'test');tick($targetWorker,$db,4);
check(!array_filter($saas->records,fn($r)=>str_starts_with($r['comment']??'','cf-saas-panel:source:'.$cnameId.':')),'explicit CNAME removal cleans all owned source revisions');
check((int)$db->value("SELECT COUNT(*) FROM managed_sources WHERE domain_id=? AND state<>'deleted'",[$cnameId])===0,'CNAME source cleanup is persisted for recovery');
